/* People: personnel files, org chart, departments, probation, right to work, rota; Hiring: requisitions, recruitment, onboarding & exit */
const money = (n, region) => region==='PK' ? 'PKR ' + Number(n||0).toLocaleString('en-GB') : gbp(n);
const nowStamp = () => D.todayIso()+' '+new Date().toTimeString().slice(0,5);
const submitOnce = (el, fn) => { if(el.dataset.busy) return; el.dataset.busy = 1; el.disabled = true; try { fn(); } finally { setTimeout(()=>{ delete el.dataset.busy; el.disabled = false; }, 600); } };

/* ---------------- PERSONNEL FILES ---------------- */
VIEWS.employees = (param) => param ? empProfile(param) : empList();
function empList(){
  const f = ST.f.emp ||= {q:'',dept:'',region:'',status:'active'};
  let list = (isHR()?DB.emps:manageable()).filter(e => (!f.q || (e.name+e.title+e.email).toLowerCase().includes(f.q.toLowerCase())) && (!f.dept || e.depts.includes(f.dept)) && (!f.region || e.region===f.region) && (!f.status || e.status===f.status));
  list = list.sort((a,b)=>a.name.localeCompare(b.name));
  return pageHead('Personnel Files', isHR()?'Core HR master data – every change is versioned and audited.':'Your team’s records (limited fields).',
    `<button class="btn" data-act="exportEmps">${ico('down')} Export</button>${isHR()?`<button class="btn pri" data-act="addEmp">${ico('plus')} Add employee</button>`:''}`) +
  `<div class="toolbar"><input type="search" class="search" placeholder="Search name, title or email" value="${esc(f.q)}" data-inp="empQ" id="eq"><select data-chg="empF" data-k="dept"><option value="">All departments</option>${deptOptions(f.dept)}</select><select data-chg="empF" data-k="region"><option value="">All regions</option>${REGIONS.map(r=>`<option ${f.region===r?'selected':''}>${r}</option>`).join('')}</select>${isHR()?`<select data-chg="empF" data-k="status"><option value="">Active &amp; leavers</option><option value="active" ${f.status==='active'?'selected':''}>Active</option><option value="leaver" ${f.status==='leaver'?'selected':''}>Leavers</option></select>`:''}<span class="muted small">${list.length} records</span></div>` +
  table([{h:'Employee',f:e=>`<div class="row">${av(e,34)}<div><b>${esc(e.name)}</b><div class="small muted">${esc(e.title)}</div></div></div>`},{h:'Department(s)',f:e=>esc(e.depts.join(' / '))},{h:'Company',f:e=>esc(e.company)},{h:'Region',f:e=>e.region},{h:'Manager',f:e=>esc(empName(e.mgr))},{h:'Start',f:e=>fmt(e.start)},{h:'Status',f:e=>e.status==='active'?badge('Active','ok'):badge('Leaver '+fmt(e.leaveDate),'bad')}], list, {row:e=>`class="click" data-act="openEmp" data-id="${e.id}"`});
}
ACT.openEmp = el => { location.hash = '#/employees/'+el.dataset.id; };
CHG.empQ = el => { ST.f.emp.q = el.value; render(); const f = $('#eq'); f.focus(); f.setSelectionRange(f.value.length,f.value.length); };
CHG.empF = el => { ST.f.emp[el.dataset.k] = el.value; render(); };
ACT.exportEmps = () => { const l = (isHR()?DB.emps:manageable()); csvDownload('personnel', ['Name','Title','Departments','Company','Region','Manager','Start date','Status','Contract','FTE'], l.map(e=>[e.name,e.title,e.depts.join(' / '),e.company,e.region,empName(e.mgr),e.start,e.status,e.contract,e.fte])); };

function empProfile(id){
  const e = emp(id); if(!e) return `<div class="banner">Employee not found. <a href="#/employees">Back</a></div>`;
  if(!isHR() && !manageable().some(x=>x.id===e.id) && e.id!==SESSION.uid) return `<div class="banner">${ico('lock')} You do not have access to this record.</div>`;
  const hrView = isHR(), k = tabOf('prof-'+id,'personal'), yr = curLY(e), b = balance(e,yr);
  const tabs = [['personal','Personal'],['employment','Employment'],['relationships','Relationships'],['dates','Key dates'],['allow','Allowance'],['shift','Shift pattern'],...(hrView?[['bank','Banking & tax']]:[]),['disc','Disciplinary'],['docs','Documents'],['hist','Version history']];
  const dl = rows => `<dl class="dl">${rows.map(([a,c])=>`<dt>${a}</dt><dd>${c||'—'}</dd>`).join('')}</dl>`;
  const body = {
    personal: dl([['Full name',esc(e.name)],['Email',esc(e.email)],['Phone',esc(e.phone)],['Date of birth',fmt(e.dob)],['Region',e.region]]),
    employment: dl([['Job title',esc(e.title)],['Company',esc(e.company)],['Department(s)',esc(e.depts.join(' / '))],['Line manager',esc(empName(e.mgr))],['Manages',esc(e.manages.join(', '))],['Contract',esc(e.contract)],['FTE',e.fte],['Grade',esc(e.grade)],['Access role',ROLES[e.role]],['Sign-in type',esc(e.signInType||'Company Microsoft account')],['Sign-in email',esc(loginEmail(e))],['Portal access',accessActive(e)?'Active':'<b style="color:var(--bad)">Disabled</b>'+(e.access&&e.access.reason?' – '+esc(e.access.reason):'')]]),
    relationships: dl([['Line manager',esc(empName(e.mgr))],['Direct reports',DB.emps.filter(x=>x.mgr===e.id&&x.status==='active').map(x=>esc(x.name)).join(', ')],['Emergency contact',esc(e.emergency.name)],['Relationship',esc(e.emergency.rel)],['Emergency phone',esc(e.emergency.phone)]]),
    dates: dl([['Start date',fmt(e.start)],['Length of service',`${Math.floor(D.diff(e.start,D.todayIso())/365.25)} years ${Math.floor((D.diff(e.start,D.todayIso())%365.25)/30.4)} months`],['Date of birth',fmt(e.dob)],['Next anniversary',fmt(upcomingDates('start',366).find(x=>x.e.id===e.id)?.date)],['Probation end',fmt(D.iso(D.add(D.parse(e.start),90)))],['Leaving date',e.leaveDate?fmt(e.leaveDate):'']]),
    allow: `<div class="grid g3">${[yr,yr+1,yr+2].map(y=>{ const bb = balance(e,y); return `<div class="card flat"><h3>${lyLabel(e,y)}</h3><dl class="dl" style="grid-template-columns:1fr auto"><dt>Entitlement</dt><dd>${num1(bb.ent)}</dd><dt>Carried</dt><dd>${num1(bb.carry)}</dd><dt>Taken</dt><dd>${num1(bb.taken)}</dd><dt>Booked</dt><dd>${num1(bb.upcoming)}</dd><dt>Pending</dt><dd>${num1(bb.pending)}</dd><dt><b>Remaining</b></dt><dd><b>${num1(bb.remaining)}</b></dd>${bb.sickEnt?`<dt>Sick allowance</dt><dd>${num1(bb.sickTaken)} / ${num1(bb.sickEnt)}</dd>`:''}</dl></div>`; }).join('')}</div>`,
    shift: shiftTab(e, hrView),
    bank: `<div class="banner info">${ico('lock')}<span>Special-category and financial fields are masked and visible to HR only. Access is logged.</span></div>`+dl([['Bank (masked)',esc(e.bank)],['Tax code',esc(e.tax)],['NI number (masked)',esc(e.ni)]]),
    disc: table([{h:'Date',f:d=>fmt(d.date)},{h:'Level',f:d=>esc(d.level)},{h:'Reason',f:d=>esc(d.reason)}], e.disc, {empty:'No disciplinary history.'}) + (DB.cases.filter(c=>c.emp===e.id).length?`<p class="small muted" style="margin-top:10px">Linked cases: ${DB.cases.filter(c=>c.emp===e.id).map(c=>`<a href="#/cases">${c.id}</a>`).join(', ')}</p>`:''),
    docs: `<div class="row sp" style="margin-bottom:10px"><span class="muted small">Attachments are limited to 300 KB in this prototype (production uses SharePoint with retention rules).</span>${hrView||e.id===SESSION.uid?`<label class="btn sm pri" style="cursor:pointer">${ico('up')} Upload<input type="file" hidden data-chg="docUp" data-id="${e.id}"></label>`:''}</div>`+table([{h:'File',f:d=>esc(d.name)},{h:'Size',f:d=>Math.round(d.size/1024)+' KB'},{h:'Uploaded',f:d=>fmtDT(d.t)},{h:'By',f:d=>esc(d.by)},{h:'',cls:'right',f:(d)=>`<button class="btn sm" data-act="docGet" data-id="${e.id}" data-n="${esc(d.name)}">${ico('down')}</button>`}], e.docs, {empty:'No documents attached.'}),
    hist: `<div class="tl">${e.history.map(h=>`<div class="e"><b>${esc(h.what)}</b><div class="small muted">${fmtDT(h.t)} · ${esc(h.by)}</div></div>`).join('')}</div>`
  }[k];
  return `<p><a href="#/employees">← Personnel files</a></p>
  <div class="card" style="margin-bottom:16px"><div class="row wrap">${av(e,72)}<div class="grow"><h1 style="font-size:22px">${esc(e.name)}</h1><div class="muted">${esc(e.title)} · ${esc(e.depts.join(' / '))} · ${esc(e.company)}</div><div style="margin-top:6px">${e.status==='active'?badge('Active','ok'):badge('Leaver','bad')} ${badge(e.region)} ${badge(ROLES[e.role],'info')}</div></div>
    <div class="row wrap">${hrView?`<button class="btn" data-act="editEmp" data-id="${e.id}">${ico('edit')} Edit</button><button class="btn" data-act="resendCred" data-id="${e.id}">${ico('mail')} Resend sign-in</button><button class="btn ${accessActive(e)?'bad':'ok'}" data-act="accessToggle" data-id="${e.id}">${accessActive(e)?'Disable access':'Enable access'}</button>`:''}<button class="btn" data-act="exportOne" data-id="${e.id}">${ico('down')} Export</button></div></div></div>
  ${tabsHtml('prof-'+id, tabs, 'personal')}<div class="card">${body}</div>`;
}
ACT.exportOne = el => { const e = emp(el.dataset.id); csvDownload('employee_'+e.name.replace(/ /g,'_'), ['Field','Value'], [['Name',e.name],['Title',e.title],['Email',e.email],['Departments',e.depts.join(' / ')],['Company',e.company],['Region',e.region],['Manager',empName(e.mgr)],['Start',e.start],['Contract',e.contract],['Shift',e.shift]]); };
CHG.docUp = el => { const f = el.files[0]; if(!f) return; if(f.size>300*1024){ toast('File is larger than 300 KB.','bad'); el.value=''; return; }
  const r = new FileReader(); r.onload = () => { const e = emp(el.dataset.id); e.docs.unshift({name:f.name,size:f.size,t:nowStamp(),by:me().name,data:r.result}); e.history.unshift({t:nowStamp(),by:me().name,what:'Document attached: '+f.name}); log('Document uploaded',f.name,e.id); saveDB(); toast('Document attached','ok'); render(); }; r.readAsDataURL(f); };
ACT.docGet = el => { const d = emp(el.dataset.id).docs.find(x=>x.name===el.dataset.n); const a = document.createElement('a'); a.href = d.data; a.download = d.name; document.body.appendChild(a); a.click(); a.remove(); log('Document downloaded',d.name,el.dataset.id); };

const EMP_FIELDS = [['name','Full name','text'],['title','Job title','text'],['email','Work email','email'],['phone','Phone','text'],['signInType','Sign-in type','sel:Company Microsoft account|Personal email account'],['personalEmail','Personal email (sign-in email for personal accounts, and welcome pack)','email'],['dob','Date of birth','date'],['start','Start date','date'],['company','Company','sel:'+COMPANIES.join('|')],['region','Region','sel:UK|PK'],['contract','Contract','text'],['fte','FTE','number'],['grade','Grade','text'],['shift','Shift pattern','text'],['role','Access role','sel:employee|manager|hr|admin']];
function empForm(e){
  const mgrs = DB.emps.filter(x=>x.status==='active' && x.id!==e.id);
  return `<form id="ef" onsubmit="return false"><div class="fgrid">${EMP_FIELDS.map(([k,l,t])=>`<div class="field"><label>${l}</label>${t.startsWith('sel:')?`<select name="${k}">${t.slice(4).split('|').map(o=>`<option value="${o}" ${String(e[k])===o?'selected':''}>${k==='role'?ROLES[o]:o}</option>`).join('')}</select>`:`<input type="${t}" name="${k}" value="${esc(e[k]??'')}" ${t==='number'?'step="0.1" min="0.1" max="1"':''}>`}</div>`).join('')}
  <div class="field"><label>Line manager</label><select name="mgr"><option value="">— None —</option>${empOptions(mgrs,e.mgr)}</select></div>
  <div class="field full"><label>Department(s) – select one or more</label><div class="row wrap">${DB.depts.map(d=>`<label class="row" style="gap:5px;margin:0;font-weight:500"><input type="checkbox" style="width:auto" name="dep" value="${esc(d)}" ${e.depts.includes(d)?'checked':''}> ${esc(d)}</label>`).join('')}</div></div></div><div id="eerr" class="err"></div></form>`;
}
ACT.editEmp = el => { const e = emp(el.dataset.id); modal({title:'Edit – '+esc(e.name),size:'wide',body:empForm(e),actions:[{label:'Cancel',act:'closeModal'},{label:'Save changes',cls:'pri',act:'saveEmp',data:`data-id="${e.id}"`}]}); };
ACT.addEmp = () => { const e = {id:'new',name:'',title:'',email:'',phone:'',dob:'',start:D.todayIso(),company:'PFG Group',region:'UK',contract:'Permanent',fte:1,grade:'G3',shift:'Mon–Fri 09:00–17:30',role:'employee',mgr:'',depts:[],signInType:'Company Microsoft account'}; modal({title:'Add employee',size:'wide',body:empForm(e),actions:[{label:'Cancel',act:'closeModal'},{label:'Create record',cls:'pri',act:'saveEmp',data:'data-id="new"'}]}); };
ACT.saveEmp = el => submitOnce(el, () => {
  const f = $('#ef'), er = $('#eerr'), isNew = el.dataset.id==='new', e = isNew ? {id:'e'+(Math.max(...DB.emps.map(x=>+x.id.slice(1)))+1),status:'active',manages:[],carry:{},extraDays:0,emergency:{name:'',rel:'',phone:''},bank:'•••• (to be entered)',tax:'—',ni:'—',docs:[],history:[],disc:[]} : emp(el.dataset.id);
  const v = {}; EMP_FIELDS.forEach(([k,,t]) => v[k] = t==='number' ? +f[k].value : f[k].value.trim()); v.mgr = f.mgr.value || null; v.depts = $$('input[name=dep]:checked',f).map(x=>x.value);
  const errs = [];
  if(v.name.length<2) errs.push('Full name is required.'); if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v.email)) errs.push('Enter a valid email address.');
  if(DB.emps.some(x=>x.id!==e.id && x.email.toLowerCase()===v.email.toLowerCase())) errs.push('That email is already used by another employee.');
  if(!v.dob || !v.start) errs.push('Date of birth and start date are required.'); else if(D.diff(v.dob,v.start) < 16*365) errs.push('Employee must be at least 16 years old at start date.');
  if(v.signInType==='Personal email account' && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v.personalEmail)) errs.push('A personal email is required for personal-email sign-in.');
  if(DB.emps.some(x=>x.id!==e.id && loginEmails(x).some(m=>[v.email.toLowerCase(), (v.signInType==='Personal email account'?v.personalEmail.toLowerCase():'')].includes(m)))) errs.push('That sign-in email is already used by another employee.');
  if(!v.depts.length) errs.push('Select at least one department.'); if(!(v.fte>0 && v.fte<=1)) errs.push('FTE must be between 0.1 and 1.');
  if(errs.length){ er.innerHTML = errs.map(esc).join('<br>'); er.classList.add('show'); return; }
  if(isNew){ Object.assign(e, v); DB.emps.push(e); e.history.unshift({t:nowStamp(),by:me().name,what:'Record created'}); log('Employee created', e.name, e.id); onNewEmployee(e); }
  else { const diffs = []; Object.keys(v).forEach(k => { const a = JSON.stringify(e[k]), b = JSON.stringify(v[k]); if(a!==b) diffs.push(`${k}: ${Array.isArray(e[k])?e[k].join('/'):e[k]??'—'} → ${Array.isArray(v[k])?v[k].join('/'):v[k]??'—'}`); Object.assign(e, {[k]:v[k]}); });
    if(diffs.length){ e.history.unshift({t:nowStamp(),by:me().name,what:'Updated – '+diffs.join('; ')}); log('Employee updated', diffs.join('; '), e.id); } }
  saveDB(); closeModal(); toast('Saved','ok'); if(isNew) location.hash = '#/employees/'+e.id; else render();
});

/* my profile + photo (HR-044) */
ACT.myProfile = () => { const u = me(); $$('.pop').forEach(p=>p.classList.remove('show')); modal({title:'My profile',body:`<div class="row" style="margin-bottom:16px">${av(u,84)}<div><label class="btn sm pri" style="cursor:pointer">${ico('up')} Change photo<input type="file" accept="image/*" hidden data-chg="photo"></label>${u.photo?`<button class="btn sm" data-act="rmPhoto">Remove</button>`:''}<div class="small muted" style="margin-top:6px">JPG or PNG. Resized automatically.</div></div></div>
  <form id="mp" onsubmit="return false"><div class="fgrid"><div class="field"><label>Phone</label><input name="phone" value="${esc(u.phone)}"></div><div class="field"><label>Emergency contact</label><input name="en" value="${esc(u.emergency.name)}"></div><div class="field"><label>Relationship</label><input name="er" value="${esc(u.emergency.rel)}"></div><div class="field"><label>Emergency phone</label><input name="ep" value="${esc(u.emergency.phone)}"></div></div></form><p class="small muted">Other details are maintained by HR. Contact HR to request a change.</p>`,actions:[{label:'Close',act:'closeModal'},{label:'Save',cls:'pri',act:'saveMyProfile'}]}); };
CHG.photo = el => { const f = el.files[0]; if(!f) return; if(!/^image\//.test(f.type)) return toast('Please choose an image.','bad'); const r = new FileReader(); r.onload = () => { const img = new Image(); img.onload = () => { const c = document.createElement('canvas'), s = 200, m = Math.min(img.width,img.height); c.width = c.height = s; c.getContext('2d').drawImage(img,(img.width-m)/2,(img.height-m)/2,m,m,0,0,s,s); me().photo = c.toDataURL('image/jpeg',.82); me().history.unshift({t:nowStamp(),by:me().name,what:'Profile photo updated'}); log('Profile photo updated',''); saveDB(); closeModal(); toast('Photo updated','ok'); render(); }; img.src = r.result; }; r.readAsDataURL(f); };
ACT.rmPhoto = () => { me().photo = null; saveDB(); closeModal(); render(); };
ACT.saveMyProfile = () => { const f = $('#mp'), u = me(); u.phone = f.phone.value.trim(); u.emergency = {name:f.en.value.trim(),rel:f.er.value.trim(),phone:f.ep.value.trim()}; u.history.unshift({t:nowStamp(),by:u.name,what:'Contact details updated by employee'}); saveDB(); closeModal(); toast('Profile saved','ok'); };

/* ---------------- ORG CHART ---------------- */
VIEWS.orgchart = () => {
  const act = DB.emps.filter(e=>e.status==='active'); const kids = id => act.filter(e=>e.mgr===id);
  const node = e => `<li><div class="onode" ${isMgr()?`data-act="openEmp" data-id="${e.id}"`:''}>${av(e,42)}<b>${esc(e.name)}</b><span>${esc(e.title)}</span><span>${esc(e.depts.join(' / '))} · ${e.region}</span></div>${kids(e.id).length?`<ul>${kids(e.id).map(node).join('')}</ul>`:''}</li>`;
  const roots = act.filter(e=>!e.mgr || !act.some(x=>x.id===e.mgr));
  return pageHead('Organisation Chart','Reporting lines across PFG Group (UK & PK). Click a person to open their file.') + `<div class="card"><div class="org"><ul>${roots.map(node).join('')}</ul></div></div>`;
};

/* ---------------- DEPARTMENTS ---------------- */
VIEWS.departments = () => pageHead('Departments','Maintain the department list and assign one or more departments to each manager.',`<button class="btn pri" data-act="addDept">${ico('plus')} Add department</button>`) +
  `<div class="grid g-main"><div class="card"><h3>Departments</h3>${table([{h:'Department',f:d=>`<b>${esc(d)}</b>`},{h:'Staff',f:d=>DB.emps.filter(e=>e.status==='active'&&e.depts.includes(d)).length},{h:'Managers',f:d=>esc(DB.emps.filter(e=>e.manages.includes(d)).map(e=>e.name).join(', '))||'<span class="muted">None</span>'},{h:'',cls:'right nowrap',f:d=>`<button class="btn sm" data-act="renDept" data-d="${esc(d)}">${ico('edit')} Rename</button> <button class="btn sm" data-act="delDept" data-d="${esc(d)}">${ico('trash')}</button>`}],DB.depts)}</div>
  <div class="card"><h3>Manager → departments</h3><p class="small muted">A manager can look after several departments and approve leave for all of them.</p>${DB.emps.filter(e=>e.status==='active'&&(e.manages.length||e.role==='manager')).map(e=>`<div class="li">${av(e,30)}<div class="grow"><b>${esc(e.name)}</b><div class="small muted">${e.manages.length?esc(e.manages.join(', ')):'No departments assigned'}</div></div><button class="btn sm" data-act="assignMgr" data-id="${e.id}">Assign</button></div>`).join('')}</div></div>`;
ACT.addDept = () => modal({title:'Add department',body:`<div class="field"><label>Name</label><input id="dn" maxlength="40"></div>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Add',cls:'pri',act:'saveDept'}]});
ACT.saveDept = () => { const n = $('#dn').value.trim(); if(n.length<2) return toast('Enter a name.','bad'); if(DB.depts.some(d=>d.toLowerCase()===n.toLowerCase())) return toast('That department already exists.','bad'); DB.depts.push(n); log('Department added',n); saveDB(); closeModal(); render(); };
ACT.renDept = el => { const d = el.dataset.d; modal({title:'Rename department',body:`<div class="field"><label>New name</label><input id="dn" value="${esc(d)}" maxlength="40"></div><p class="small muted">Employees, managers and rota entries are updated automatically.</p>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Rename',cls:'pri',act:'saveRen',data:`data-d="${esc(d)}"`}]}); };
ACT.saveRen = el => { const o = el.dataset.d, n = $('#dn').value.trim(); if(n.length<2) return toast('Enter a name.','bad'); if(n!==o && DB.depts.some(d=>d.toLowerCase()===n.toLowerCase())) return toast('That name is already used.','bad');
  DB.depts = DB.depts.map(d=>d===o?n:d); DB.emps.forEach(e=>{ e.depts = e.depts.map(d=>d===o?n:d); e.manages = e.manages.map(d=>d===o?n:d); }); log('Department renamed',`${o} → ${n}`); saveDB(); closeModal(); toast('Department updated','ok'); render(); };
ACT.delDept = el => { const d = el.dataset.d, n = DB.emps.filter(e=>e.status==='active'&&e.depts.includes(d)).length; if(n) return toast(`${n} active employee(s) are in ${d}. Move them first.`,'bad'); confirmBox(`Delete department <b>${esc(d)}</b>?`, () => { DB.depts = DB.depts.filter(x=>x!==d); DB.emps.forEach(e=>{ e.manages = e.manages.filter(x=>x!==d); }); log('Department deleted',d); saveDB(); render(); }, 'Delete'); };
ACT.assignMgr = el => { const e = emp(el.dataset.id); modal({title:`Departments managed by ${esc(e.name)}`,body:`<div class="grid g2">${DB.depts.map(d=>`<label class="row" style="margin:0;gap:8px"><input type="checkbox" style="width:auto" name="md" value="${esc(d)}" ${e.manages.includes(d)?'checked':''}> ${esc(d)}</label>`).join('')}</div>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Save',cls:'pri',act:'saveMgr',data:`data-id="${e.id}"`}]}); };
ACT.saveMgr = el => { const e = emp(el.dataset.id); e.manages = $$('input[name=md]:checked').map(x=>x.value); if(e.manages.length && e.role==='employee') e.role = 'manager'; e.history.unshift({t:nowStamp(),by:me().name,what:'Manages: '+(e.manages.join(', ')||'none')}); log('Manager departments updated',e.manages.join(', '),e.id); saveDB(); closeModal(); toast('Saved','ok'); render(); };

/* ---------------- PROBATION ---------------- */
VIEWS.probation = () => {
  const rows = DB.probation.filter(p => isHR() || manageable().some(m=>m.id===p.emp));
  return pageHead('Probation 30 / 60 / 90','Checkpoints are created automatically from the start date. Outcomes: confirm, extend or exit.') +
   `<div class="grid g2">${rows.map(p => { const e = emp(p.emp); return `<div class="card"><div class="row">${av(e,40)}<div class="grow"><b>${esc(e.name)}</b><div class="small muted">${esc(e.title)} · started ${fmt(p.start)}</div></div></div>
    <div class="steps" style="margin-top:14px">${[30,60,90].map(n => { const due = D.iso(D.add(D.parse(p.start),n)), done = !!p.reviews[n], over = !done && due<D.todayIso(); return `<div class="step ${done?'done':over?'rej':''}"><i>${done?'✓':n}</i>Day ${n}<div class="small">${fmtS(due)}</div></div>`; }).join('')}</div>
    ${[30,60,90].map(n => { const due = D.iso(D.add(D.parse(p.start),n)); return `<div class="li"><span style="width:60px"><b>Day ${n}</b></span><span class="grow small">${p.reviews[n]?esc(p.reviews[n]):(due<D.todayIso()?badge('Overdue','bad'):badge('Due '+fmtS(due),'warn'))}</span>${!p.reviews[n]&&isMgr()?`<button class="btn sm" data-act="probRev" data-e="${p.emp}" data-n="${n}">Record</button>`:''}</div>`; }).join('')}</div>`; }).join('')||'<div class="card empty">No employees on probation.</div>'}</div>`;
};
ACT.probRev = el => modal({title:`Day ${el.dataset.n} probation review – ${esc(empName(el.dataset.e))}`,body:`<div class="field"><label>Outcome</label><select id="po"><option>Confirm</option><option>Extend</option><option>Exit</option><option>On track</option></select></div><div class="field"><label>Notes</label><textarea id="pn"></textarea></div>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Save',cls:'pri',act:'probSave',data:`data-e="${el.dataset.e}" data-n="${el.dataset.n}"`}]});
ACT.probSave = el => { const p = DB.probation.find(x=>x.emp===el.dataset.e); p.reviews[el.dataset.n] = `${$('#po').value}${$('#pn').value.trim()?' – '+$('#pn').value.trim():''} (${me().name}, ${fmtS(D.todayIso())})`; log('Probation review',`Day ${el.dataset.n}: ${$('#po').value}`,p.emp); saveDB(); closeModal(); render(); };

/* ---------------- RIGHT TO WORK ---------------- */
VIEWS.rtw = () => {
  const today = D.todayIso(), rows = DB.rtwChecks.map(r => ({...r, left: r.expiry ? D.diff(today,r.expiry) : null})).sort((a,b)=>(a.left??9e9)-(b.left??9e9));
  const st = r => r.left===null ? badge('No expiry','ok') : r.left<0 ? badge('Expired – block scheduling','bad') : r.left<=30 ? badge('Due ≤30 days','bad') : r.left<=60 ? badge('Due ≤60 days','warn') : badge('Valid','ok');
  return pageHead('Right to Work & Visa / Permit','Share codes, PVNs and expiries. Alerts at 60 and 30 days; expired checks gate scheduling.',`<button class="btn pri" data-act="addRtw">${ico('plus')} Record check</button>`) +
  `<div class="grid g4" style="margin-bottom:16px">${[['Valid',rows.filter(r=>r.left===null||r.left>60).length,'#15803d'],['Due ≤ 60 days',rows.filter(r=>r.left!==null&&r.left>30&&r.left<=60).length,'#b45309'],['Due ≤ 30 days',rows.filter(r=>r.left!==null&&r.left>=0&&r.left<=30).length,'#b91c1c'],['Expired',rows.filter(r=>r.left!==null&&r.left<0).length,'#7f1d1d']].map(([t,n,c])=>`<div class="card kpi"><span class="t">${t}</span><span class="v" style="color:${c}">${n}</span></div>`).join('')}</div>` +
  table([{h:'Employee',f:r=>`<div class="row">${av(r.emp,28)}<b>${esc(empName(r.emp))}</b></div>`},{h:'Document',f:r=>esc(r.type)},{h:'Reference',f:r=>esc(r.ref)},{h:'Restrictions',f:r=>esc(r.restriction)},{h:'Last verified',f:r=>fmt(r.verified)},{h:'Expiry',f:r=>r.expiry?fmt(r.expiry)+` <span class="small muted">(${r.left<0?Math.abs(r.left)+' days ago':r.left+' days'})</span>`:'—'},{h:'Status',f:st},{h:'',cls:'right nowrap',f:r=>r.left!==null&&r.left<=60?`<button class="btn sm" data-act="rtwChase" data-e="${r.emp}">Request update</button> <button class="btn sm" data-act="rtwVerify" data-e="${r.emp}">Verify</button>`:''}],rows);
};
ACT.rtwChase = el => { notify(el.dataset.e,'Your right-to-work document is due to expire. Please upload your new share code / permit to HR.','dashboard'); log('RTW update requested','',el.dataset.e); saveDB(); toast('Reminder sent to employee','ok'); };
ACT.rtwVerify = el => modal({title:'Record verification – '+esc(empName(el.dataset.e)),body:`<form id="rv"><div class="fgrid"><div class="field"><label>New expiry (blank = none)</label><input type="date" name="x"></div><div class="field"><label>Verified date</label><input type="date" name="v" value="${D.todayIso()}"></div></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Save',cls:'pri',act:'rtwVerSave',data:`data-e="${el.dataset.e}"`}]});
ACT.rtwVerSave = el => { const r = DB.rtwChecks.find(x=>x.emp===el.dataset.e), f = $('#rv'); r.expiry = f.x.value; r.verified = f.v.value; log('RTW verified','',r.emp); saveDB(); closeModal(); render(); };
ACT.addRtw = () => modal({title:'Record right-to-work check',body:`<form id="rv"><div class="fgrid"><div class="field full"><label>Employee</label><select name="e">${empOptions(DB.emps.filter(e=>e.status==='active'))}</select></div><div class="field"><label>Document type</label><select name="t"><option>Share code</option><option>British passport</option><option>Visa (Skilled Worker)</option><option>Biometric residence permit</option><option>ECS PVN</option></select></div><div class="field"><label>Reference (masked)</label><input name="r" placeholder="W•••••••"></div><div class="field"><label>Expiry</label><input type="date" name="x"></div><div class="field"><label>Restrictions</label><input name="rs" value="None"></div></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Save',cls:'pri',act:'rtwAddSave'}]});
ACT.rtwAddSave = () => { const f = $('#rv'); DB.rtwChecks = DB.rtwChecks.filter(x=>x.emp!==f.e.value); DB.rtwChecks.push({emp:f.e.value,type:f.t.value,ref:f.r.value||'—',expiry:f.x.value,restriction:f.rs.value||'None',verified:D.todayIso()}); log('RTW recorded','',f.e.value); saveDB(); closeModal(); render(); };

/* ---------------- ROTA ---------------- */
const SHIFTS = {OFF:['Off','#eef1f7','#66758c',0],E:['Early 06–14','#dbeafe','#1d4ed8',8],D:['Day 09–17:30','#dcfce7','#15803d',8],L:['Late 14–22','#fef3c7','#b45309',8],N:['Night 22–06','#e9d5ff','#7e22ce',8]};
VIEWS.rota = () => {
  const s = ST.rota ||= {wk:D.iso(mondayOf(D.today())),dept:''}; const myDepts = isHR()?DB.depts:(me().manages.length?me().manages:me().depts); if(!s.dept || !myDepts.includes(s.dept)) s.dept = myDepts[0];
  const days = Array.from({length:7},(_,i)=>D.iso(D.add(D.parse(s.wk),i))), staff = DB.emps.filter(e=>e.status==='active' && e.depts.includes(s.dept));
  const key = s.dept+'|'+s.wk, R = DB.rota[key] ||= {};
  const cell = (e,d,i) => { const lv = DB.leave.find(l=>l.emp===e.id && l.status==='approved' && d>=l.start && d<=l.end && l.type!=='WFH'); const ph = phName(d,e.region);
    if(lv) return `<td title="${esc(LT[lv.type].name)}"><span class="shift" style="background:${LT[lv.type].c};color:${LT[lv.type].fg};border:1px solid #cfd7e6;cursor:default">${LT[lv.type].code}</span></td>`;
    if(ph) return `<td title="${esc(ph.name)}"><span class="shift" style="background:#fff3c4;color:#6b5400;cursor:default">PH</span></td>`;
    const c = (R[e.id]||{})[d] || defShift(e,d); const [l,bg,fg] = SHIFTS[c]; return `<td><span class="shift" style="background:${bg};color:${fg}" data-act="rotaCell" data-e="${e.id}" data-d="${d}">${l.split(' ')[0]}</span></td>`; };
  const code = (e,d,i) => { const lv = DB.leave.find(l=>l.emp===e.id && l.status==='approved' && d>=l.start && d<=l.end && l.type!=='WFH'); if(lv||phName(d,e.region)) return 'OFF'; return (R[e.id]||{})[d] || defShift(e,d); };
  const hrs = e => days.reduce((t,d,i)=>t+SHIFTS[code(e,d,i)][3],0);
  return pageHead('Rota','Weekly rota with shift templates, leave overlay, coverage and hours checks. Click a shift to change it.',`<button class="btn" data-act="rotaCopy">Copy to next week</button><button class="btn" data-act="rotaExport">${ico('down')} Export</button>`) +
  `<div class="toolbar"><button class="nb" data-act="rotaPrev">${ico('l')}</button><button class="nb" data-act="rotaNext">${ico('r')}</button><b style="color:var(--blue)">${fmt(days[0])} – ${fmt(days[6])}</b><select data-chg="rotaDept" style="width:auto">${myDepts.map(d=>`<option ${d===s.dept?'selected':''}>${esc(d)}</option>`).join('')}</select><span class="grow"></span>${Object.entries(SHIFTS).map(([k,[l,bg,fg]])=>`<span class="shift" style="background:${bg};color:${fg};cursor:default">${l}</span>`).join('')}</div>
  <div class="tw"><table class="rota"><thead><tr><th>Employee</th>${days.map(d=>`<th>${DAYS[D.parse(d).getDay()].slice(0,3)}<br><span class="small muted">${D.parse(d).getDate()}</span></th>`).join('')}<th>Hours</th></tr></thead><tbody>
  ${staff.map(e=>`<tr><td class="n">${esc(e.name)}</td>${days.map((d,i)=>cell(e,d,i)).join('')}<td>${hrs(e)>48?badge(hrs(e)+' h – over 48','bad'):hrs(e)+' h'}</td></tr>`).join('')||`<tr><td colspan="9" class="empty">No staff in this department.</td></tr>`}
  <tr><td class="n">Coverage</td>${days.map((d,i)=>{ const n = staff.filter(e=>code(e,d,i)!=='OFF').length, pct = staff.length?n/staff.length:0; return `<td style="background:rgba(6,138,162,${(pct*.35).toFixed(2)});font-weight:700">${n}/${staff.length}</td>`; }).join('')}<td></td></tr></tbody></table></div>
  <p class="small muted" style="margin-top:10px">Hours assume 8 h per shift. The 48-hour flag is an <b>assumption</b> (Working Time Regulations guide) – configure per policy. The rota vs attendance cross-check (Paxton) is a Phase 3 integration.</p>`;
};
ACT.rotaCell = el => { const s = ST.rota, key = s.dept+'|'+s.wk, R = DB.rota[key] ||= {}, i = days7(s.wk).indexOf(el.dataset.d); const order = Object.keys(SHIFTS); const cur = (R[el.dataset.e]||{})[el.dataset.d] || defShift(emp(el.dataset.e), el.dataset.d); (R[el.dataset.e] ||= {})[el.dataset.d] = order[(order.indexOf(cur)+1)%order.length]; saveDB(); render(); };
const days7 = wk => Array.from({length:7},(_,i)=>D.iso(D.add(D.parse(wk),i)));
ACT.rotaPrev = () => { ST.rota.wk = D.iso(D.add(D.parse(ST.rota.wk),-7)); render(); }; ACT.rotaNext = () => { ST.rota.wk = D.iso(D.add(D.parse(ST.rota.wk),7)); render(); };
CHG.rotaDept = el => { ST.rota.dept = el.value; render(); };
ACT.rotaCopy = () => { const s = ST.rota, nw = D.iso(D.add(D.parse(s.wk),7)), src = DB.rota[s.dept+'|'+s.wk] || {}, out = {}; Object.entries(src).forEach(([e,m]) => { out[e] = {}; Object.entries(m).forEach(([d,c]) => out[e][D.iso(D.add(D.parse(d),7))] = c); }); DB.rota[s.dept+'|'+nw] = out; saveDB(); toast('Copied to next week','ok'); ACT.rotaNext(); };
ACT.rotaExport = () => { const s = ST.rota, days = days7(s.wk), R = DB.rota[s.dept+'|'+s.wk]||{}; csvDownload('rota_'+s.dept.replace(/\W/g,''), ['Employee',...days], DB.emps.filter(e=>e.status==='active'&&e.depts.includes(s.dept)).map(e=>[e.name,...days.map((d,i)=>{ const lv = DB.leave.find(l=>l.emp===e.id&&l.status==='approved'&&d>=l.start&&d<=l.end&&l.type!=='WFH'); return lv?LT[lv.type].code:SHIFTS[(R[e.id]||{})[d]||defShift(e,d)][0]; })])); };

/* ---------------- REQUISITIONS ---------------- */
const RQ_STEPS = ['Issued by Line Manager','Received by HR','Submitted to CEO','CEO decision'];
const RQ_SLA = {1:2, 2:3}; // working days (assumption)
const isCEO = () => /chief executive/i.test(me().title);
VIEWS.requisitions = () => {
  const list = DB.requisitions.filter(r => isHR() || isCEO() || r.by===SESSION.uid || manageable().some(m=>m.id===r.by));
  const wait = r => { const last = r.audit[r.audit.length-1]; return D.diff(last.t, D.todayIso()); };
  return pageHead('Requisitions','Line Manager → HR → CEO approval with SLA tracking, budget control and a full audit trail.',`<button class="btn pri" data-act="newReq">${ico('plus')} Raise requisition</button>`) +
  `<div class="grid g4" style="margin-bottom:16px">${[['Awaiting HR',list.filter(r=>r.stage===1).length],['Awaiting CEO',list.filter(r=>r.stage===2).length],['Revision requested',list.filter(r=>r.stage===0).length],['Approved',list.filter(r=>r.stage===3).length]].map(([t,n])=>`<div class="card kpi"><span class="t">${t}</span><span class="v">${n}</span></div>`).join('')}</div>` +
  table([{h:'Ref',f:r=>`<b>${r.id}</b>`},{h:'Role',f:r=>`${esc(r.title)}<div class="small muted">${esc(r.dept)} · ${r.region} · ${esc(r.reason)} × ${r.headcount}</div>`},{h:'Budget check',f:r=>{ const t = r.salary*r.headcount; return t<=r.budget?badge('Within budget','ok'):badge('Over by '+money(t-r.budget,r.region),'bad'); }},{h:'Stage',f:r=>r.stage===3?badge('Approved','ok'):r.stage===4?badge('Rejected','bad'):r.stage===0?badge('Revision requested','warn'):badge(r.stage===1?'With HR':'With CEO','info')},{h:'SLA',f:r=>{ if(![1,2].includes(r.stage)) return '—'; const w = wait(r), s = RQ_SLA[r.stage]; return w>s?badge(`${w}d – breached (${s}d)`,'bad'):badge(`${w}d of ${s}d`,'ok'); }},{h:'',cls:'right',f:r=>`<button class="btn sm" data-act="openReq" data-id="${r.id}">Open</button>`}], list);
};
ACT.newReq = () => reqModal(); ACT.openReq = el => reqView(el.dataset.id);
function reqModal(r){
  const mine = isHR() ? DB.depts : [...new Set([...me().manages, ...me().depts])]; r = r || {title:'',dept:mine[0],region:me().region,reason:'Growth',headcount:1,budget:'',salary:''};
  modal({title:r.id?'Revise requisition '+r.id:'Raise requisition',body:`<form id="rq" onsubmit="return false"><div class="fgrid"><div class="field full"><label>Role title</label><input name="title" value="${esc(r.title)}"></div><div class="field"><label>Department</label><select name="dept">${mine.map(d=>`<option ${d===r.dept?'selected':''}>${esc(d)}</option>`).join('')}</select></div><div class="field"><label>Region</label><select name="region">${REGIONS.map(x=>`<option ${x===r.region?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Reason</label><select name="reason">${['Growth','Backfill','Temporary cover'].map(x=>`<option ${x===r.reason?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Headcount</label><input type="number" name="headcount" min="1" max="50" value="${r.headcount}"></div><div class="field"><label>Approved budget (total, ${r.region==='PK'?'PKR':'£'})</label><input type="number" name="budget" min="0" step="any" value="${r.budget}"></div><div class="field"><label>Salary per head (annual)</label><input type="number" name="salary" min="0" step="any" value="${r.salary}"></div></div><div id="rqe" class="err"></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:r.id?'Resubmit':'Submit to HR',cls:'pri',act:'saveReq',data:`data-id="${r.id||''}"`}]});
}
ACT.saveReq = el => submitOnce(el, () => { const f = $('#rq'), er = $('#rqe'); const v = {title:f.title.value.trim(),dept:f.dept.value,region:f.region.value,reason:f.reason.value,headcount:+f.headcount.value,budget:+f.budget.value,salary:+f.salary.value};
  const errs = []; if(v.title.length<3) errs.push('Role title is required.'); if(!(v.headcount>=1)) errs.push('Headcount must be at least 1.'); if(!(v.budget>0)) errs.push('Enter the approved budget.'); if(!(v.salary>0)) errs.push('Enter the salary per head.');
  if(errs.length){ er.innerHTML = errs.join('<br>'); er.classList.add('show'); return; }
  const id = el.dataset.id; let r;
  if(id){ r = DB.requisitions.find(x=>x.id===id); Object.assign(r,v,{stage:1,status:'In progress'}); r.audit.push({t:D.todayIso(),who:me().name,what:'Revised and resubmitted to HR'}); }
  else { r = {id:'RQ-'+(1001+DB.requisitions.length+Math.floor(Math.random()*0)),...v,by:me().id,created:D.todayIso(),stage:1,status:'In progress',audit:[{t:D.todayIso(),who:me().name,what:'Raised by Line Manager'}],comments:[]}; while(DB.requisitions.some(x=>x.id===r.id)) r.id = 'RQ-'+(+r.id.slice(3)+1); DB.requisitions.push(r); }
  notify(DB.emps.filter(x=>x.role==='hr'||x.role==='admin').map(x=>x.id), `Requisition ${r.id} (${r.title}) received for HR review.`, 'requisitions'); log('Requisition submitted', r.id); saveDB(); closeModal(); toast('Submitted to HR','ok'); render(); });
function reqView(id){
  const r = DB.requisitions.find(x=>x.id===id), total = r.salary*r.headcount, ok = total<=r.budget, st = r.stage;
  const canHR = isHR() && st===1, canCEO = (isCEO()||isAdmin()) && st===2, canRev = st===0 && (r.by===SESSION.uid || isHR());
  modal({title:`${r.id} – ${esc(r.title)}`,size:'wide',body:`<div class="steps">${RQ_STEPS.map((s,i)=>`<div class="step ${st===3||st===4?(i<3||st===3?'done':'rej'):(st===0?(i===0?'cur':''):i<st?'done':i===st?'cur':'')}"><i>${i+1}</i>${s}</div>`).join('')}</div>
  <div class="grid g2"><dl class="dl"><dt>Department</dt><dd>${esc(r.dept)} (${r.region})</dd><dt>Reason</dt><dd>${esc(r.reason)}</dd><dt>Headcount</dt><dd>${r.headcount}</dd><dt>Raised by</dt><dd>${esc(empName(r.by))}, ${fmt(r.created)}</dd></dl>
  <dl class="dl"><dt>Salary / head</dt><dd>${money(r.salary,r.region)}</dd><dt>Total cost</dt><dd>${money(total,r.region)}</dd><dt>Budget</dt><dd>${money(r.budget,r.region)}</dd><dt>Budget check</dt><dd>${ok?badge('Within budget','ok'):badge('Over by '+money(total-r.budget,r.region),'bad')}</dd></dl></div>
  ${r.comments.length?`<div class="banner">${ico('warn')}<span>${r.comments.map(esc).join('<br>')}</span></div>`:''}
  ${(canHR||canCEO||canRev)?`<div class="field"><label>Comment ${canRev?'':'(required to reject or return)'}</label><textarea id="rqc"></textarea></div>`:''}
  <h4 style="margin:14px 0 8px">Approval audit trail</h4><div class="tl">${r.audit.map(a=>`<div class="e"><b>${esc(a.what)}</b><div class="small muted">${fmt(a.t)} · ${esc(a.who)}</div></div>`).join('')}</div>`,
  actions:[{label:'Close',act:'closeModal'},...(canRev?[{label:'Revise & resubmit',cls:'pri',act:'reqRevise',data:`data-id="${id}"`}]:[]),...(canHR?[{label:'Return for revision',act:'reqReturn',data:`data-id="${id}"`},{label:ok?'Submit to CEO':'Submit to CEO (over budget)',cls:'pri',act:'reqToCEO',data:`data-id="${id}"`}]:[]),...(canCEO?[{label:'Return',act:'reqReturn',data:`data-id="${id}"`},{label:'Reject',cls:'bad',act:'reqReject',data:`data-id="${id}"`},{label:'Approve',cls:'ok',act:'reqApprove',data:`data-id="${id}"`}]:[])]});
}
const rqAudit = (r,what) => r.audit.push({t:D.todayIso(),who:me().name,what});
const rqComment = () => ($('#rqc')?.value||'').trim();
ACT.reqRevise = el => { const r = DB.requisitions.find(x=>x.id===el.dataset.id); reqModal(r); };
ACT.reqReturn = el => { const r = DB.requisitions.find(x=>x.id===el.dataset.id), c = rqComment(); if(!c) return toast('A comment is required.','bad'); r.stage = 0; r.status='Revision requested'; r.comments = [c]; rqAudit(r,'Returned for revision: '+c); notify(r.by, `Requisition ${r.id} was returned for revision: ${c}`, 'requisitions'); log('Requisition returned', r.id); saveDB(); closeModal(); render(); };
ACT.reqToCEO = el => { const r = DB.requisitions.find(x=>x.id===el.dataset.id), ok = r.salary*r.headcount<=r.budget; if(!ok && !rqComment()) return toast('Add a comment justifying the over-budget request.','bad'); r.stage = 2; r.comments = []; rqAudit(r, `Received by HR; budget check ${ok?'passed':'FAILED – submitted with justification: '+rqComment()}`); rqAudit(r,'Submitted to CEO'); notify(DB.emps.filter(x=>/chief executive/i.test(x.title)).map(x=>x.id), `Requisition ${r.id} awaits your approval.`, 'requisitions'); log('Requisition to CEO', r.id); saveDB(); closeModal(); render(); };
ACT.reqApprove = el => { const r = DB.requisitions.find(x=>x.id===el.dataset.id); r.stage = 3; r.status='Approved'; rqAudit(r, isCEO()?'Approved by CEO':`CEO approval recorded by ${me().name} on behalf of CEO`); notify([r.by], `Requisition ${r.id} was approved.`, 'requisitions'); log('Requisition approved', r.id); saveDB(); closeModal(); toast('Approved','ok'); render(); };
ACT.reqReject = el => { const r = DB.requisitions.find(x=>x.id===el.dataset.id), c = rqComment(); if(!c) return toast('A comment is required.','bad'); r.stage = 4; r.status='Rejected'; r.comments=[c]; rqAudit(r,'Rejected: '+c); notify([r.by], `Requisition ${r.id} was rejected: ${c}`, 'requisitions'); log('Requisition rejected', r.id); saveDB(); closeModal(); render(); };

/* ---------------- RECRUITMENT ---------------- */
const STAGES = ['Sourcing','Screening','Interview 1','Interview 2','Offer','Checks','Hired'];
const CRIT = ['Skills','Experience','Attitude','Fit'];
const KEYWORDS = ['forklift','flt','sap','excel','sql','power bi','dax','fabric','python','tableau','health and safety','stock control','team leadership','supervisor','route planning','logistics','manual handling','food hygiene','finance','reporting','data modelling','dashboards','customer service','negotiation'];
const parseCV = txt => KEYWORDS.filter(k => txt.toLowerCase().includes(k));
const avgScore = c => { const v = Object.values(c.scores).flatMap(s=>Object.values(s)); return v.length ? (v.reduce((a,b)=>a+b,0)/v.length).toFixed(1) : '—'; };
VIEWS.recruitment = () => {
  const tabs = [['pipe','Pipeline'],['jobs','Job posts'],['cv','CV bank']], k = tabOf('rec','pipe');
  let body = '';
  if(k==='pipe'){ const jf = ST.f.recJob||''; const cs = DB.candidates.filter(c=>c.stage!=='Rejected' && (!jf||c.job===jf));
    body = `<div class="toolbar"><select data-chg="recJob"><option value="">All vacancies</option>${DB.jobs.map(j=>`<option value="${j.id}" ${jf===j.id?'selected':''}>${esc(j.title)} (${j.type})</option>`).join('')}</select><span class="grow"></span><span class="muted small">${cs.length} active candidates · hired ${DB.candidates.filter(c=>c.stage==='Hired').length}</span></div>
    <div class="kan">${STAGES.map(s=>`<div class="kcol"><h4>${s}<span>${cs.filter(c=>c.stage===s).length}</span></h4>${cs.filter(c=>c.stage===s).map(c=>`<div class="kc" data-act="openCand" data-id="${c.id}"><b>${esc(c.name)}</b><div class="small muted">${esc(DB.jobs.find(j=>j.id===c.job)?.title||'')}</div><div class="row sp small" style="margin-top:6px"><span>${esc(c.source)}</span><span>${avgScore(c)!=='—'?'★ '+avgScore(c):''}</span></div></div>`).join('')}</div>`).join('')}</div>`; }
  if(k==='jobs') body = `<div class="toolbar"><span class="grow"></span><button class="btn pri" data-act="newJob">${ico('plus')} Post a job</button></div>` + table([{h:'Title',f:j=>`<b>${esc(j.title)}</b><div class="small muted">${esc(j.dept)} · ${esc(j.loc)}</div>`},{h:'Audience',f:j=>badge(j.type,j.type==='Internal'?'pur':'info')},{h:'Requisition',f:j=>j.req||'—'},{h:'Posted',f:j=>fmt(j.posted)},{h:'Applicants',f:j=>DB.candidates.filter(c=>c.job===j.id).length},{h:'Status',f:j=>statusBadge(j.status)},{h:'',cls:'right',f:j=>`<button class="btn sm" data-act="toggleJob" data-id="${j.id}">${j.status==='Open'?'Close':'Reopen'}</button>`}], DB.jobs);
  if(k==='cv'){ const q = ST.f.cvq||''; body = `<div class="toolbar"><input type="search" class="search" placeholder="Search skills e.g. power bi, forklift" value="${esc(q)}" data-inp="cvq" id="cvq"><span class="grow"></span><button class="btn" data-act="bulkCV">${ico('up')} Bulk upload (CSV)</button><button class="btn pri" data-act="newCand">${ico('plus')} Add candidate / CV</button></div><div class="banner info">${ico('help')}<span>CV parsing here is a <b>rule-based simulation</b> (keyword extraction). Production would use AI parsing with human review of every shortlist decision.</span></div>` + table([{h:'Candidate',f:c=>`<b>${esc(c.name)}</b><div class="small muted">${esc(c.email)}</div>`},{h:'Parsed skills',f:c=>parseCV(c.cv).map(s=>`<span class="tag">${esc(s)}</span>`).join('')||'—'},{h:'Applied for',f:c=>esc(DB.jobs.find(j=>j.id===c.job)?.title||'—')},{h:'Stage',f:c=>statusBadge(c.stage)},{h:'Source',f:c=>esc(c.source)}], DB.candidates.filter(c=>!q||(c.cv+c.name).toLowerCase().includes(q.toLowerCase())), {row:c=>`class="click" data-act="openCand" data-id="${c.id}"`}); }
  return pageHead('Recruitment (ATS)','Pipelines, multi-stage interviews, scoring matrix, CV bank and job posts.',`<button class="btn" data-act="go" data-to="requisitions">Requisitions</button>`) + tabsHtml('rec',tabs,'pipe') + body;
};
CHG.recJob = el => { ST.f.recJob = el.value; render(); };
CHG.cvq = el => { ST.f.cvq = el.value; render(); const f = $('#cvq'); f.focus(); f.setSelectionRange(f.value.length,f.value.length); };
ACT.toggleJob = el => { const j = DB.jobs.find(x=>x.id===el.dataset.id); j.status = j.status==='Open'?'Closed':'Open'; log('Job post '+j.status.toLowerCase(), j.title); saveDB(); render(); };
ACT.newJob = () => { const reqs = DB.requisitions.filter(r=>r.stage===3); modal({title:'Post a job',body:`<form id="jf"><div class="fgrid"><div class="field full"><label>Linked approved requisition</label><select name="req" data-chg="jobReq"><option value="">— Select —</option>${reqs.map(r=>`<option value="${r.id}">${r.id} – ${esc(r.title)}</option>`).join('')}</select></div><div class="field"><label>Title</label><input name="title"></div><div class="field"><label>Department</label><select name="dept">${deptOptions()}</select></div><div class="field"><label>Audience</label><select name="type"><option>Internal</option><option>External</option></select></div><div class="field"><label>Location</label><input name="loc"></div></div><p class="small muted">Jobs should only be posted against an approved requisition (headcount control).</p><div id="jfe" class="err"></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Publish',cls:'pri',act:'saveJob'}]}); };
CHG.jobReq = el => { const r = DB.requisitions.find(x=>x.id===el.value), f = $('#jf'); if(r){ f.title.value = r.title; f.dept.value = r.dept; } };
ACT.saveJob = () => { const f = $('#jf'), er = $('#jfe'); if(f.title.value.trim().length<3 || !f.loc.value.trim()){ er.textContent='Title and location are required.'; er.classList.add('show'); return; } if(!f.req.value && !isAdmin()){ er.textContent='Link an approved requisition first.'; er.classList.add('show'); return; }
  DB.jobs.push({id:uid('J'),title:f.title.value.trim(),dept:f.dept.value,type:f.type.value,loc:f.loc.value.trim(),status:'Open',posted:D.todayIso(),req:f.req.value}); log('Job posted',f.title.value); saveDB(); closeModal(); render(); };
ACT.newCand = () => modal({title:'Add candidate / CV',body:`<form id="cf"><div class="fgrid"><div class="field"><label>Name</label><input name="name"></div><div class="field"><label>Email</label><input type="email" name="email"></div><div class="field"><label>Vacancy</label><select name="job">${DB.jobs.map(j=>`<option value="${j.id}">${esc(j.title)}</option>`).join('')}</select></div><div class="field"><label>Source</label><select name="source"><option>Job board</option><option>Referral</option><option>Agency</option><option>LinkedIn</option><option>Internal</option></select></div><div class="field full"><label>CV text (paste) – skills are extracted automatically</label><textarea name="cv" style="min-height:110px"></textarea></div></div><p class="small muted">Candidate data is subject to the retention schedule (jurisdictional). Do not paste special-category data.</p><div id="cfe" class="err"></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Add',cls:'pri',act:'saveCand'}]});
ACT.saveCand = () => { const f = $('#cf'), er = $('#cfe'); if(f.name.value.trim().length<2 || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(f.email.value)){ er.textContent='Enter a name and a valid email.'; er.classList.add('show'); return; }
  DB.candidates.push({id:uid('c'),name:f.name.value.trim(),email:f.email.value.trim(),job:f.job.value,source:f.source.value,stage:'Sourcing',cv:f.cv.value,scores:{}}); log('Candidate added',f.name.value); saveDB(); closeModal(); render(); };
ACT.bulkCV = () => modal({title:'Bulk upload candidates',body:`<p class="small muted">CSV with header: <code>name,email,job,source,cv</code>. Job = vacancy id (${DB.jobs.map(j=>j.id).join(', ')}).</p><input type="file" accept=".csv" data-chg="bulkCSV">`,actions:[{label:'Close',act:'closeModal'},{label:'Download template',act:'cvTemplate'}]});
ACT.cvTemplate = () => fileDownload('candidates_template.csv','name,email,job,source,cv\n"Jane Example","jane@example.com","J1","Job board","forklift, stock control"\n','text/csv');
CHG.bulkCSV = el => { const f = el.files[0]; if(!f) return; const r = new FileReader(); r.onload = () => { const rows = r.result.replace(/^﻿/,'').split(/\r?\n/).filter(Boolean).slice(1); let n = 0, bad = 0; rows.forEach(line => { const m = line.match(/("([^"]|"")*"|[^,]*)(,|$)/g)?.map(x=>x.replace(/,$/,'').replace(/^"|"$/g,'').replace(/""/g,'"')); if(!m || m.length<5 || !/^[^@\s]+@[^@\s]+$/.test(m[1]) || !DB.jobs.some(j=>j.id===m[2])){ bad++; return; } DB.candidates.push({id:uid('c'),name:m[0],email:m[1],job:m[2],source:m[3]||'Upload',stage:'Sourcing',cv:m[4]||'',scores:{}}); n++; }); log('Bulk candidate upload',`${n} added, ${bad} rejected`); saveDB(); closeModal(); toast(`${n} added${bad?`, ${bad} rows rejected`:''}`, bad?'':'ok'); render(); }; r.readAsText(f); };
ACT.openCand = el => candModal(el.dataset.id);
function candModal(id){
  const c = DB.candidates.find(x=>x.id===id), j = DB.jobs.find(x=>x.id===c.job), si = STAGES.indexOf(c.stage), sk = parseCV(c.cv), jk = parseCV((j?.title||'')+' '+DB.candidates.filter(x=>x.job===c.job&&x.stage==='Hired').map(x=>x.cv).join(' '));
  const stageNo = si>=2 && si<=3 ? si-1 : null;
  modal({title:esc(c.name),size:'wide',body:`<div class="row sp wrap"><div><div class="muted">${esc(c.email)} · ${esc(c.source)}</div><div>Applied for <b>${esc(j?.title||'—')}</b></div></div>${statusBadge(c.stage)}</div>
  <div class="steps" style="margin-top:12px">${STAGES.map((s,i)=>`<div class="step ${i<si?'done':i===si?'cur':''}"><i>${i+1}</i>${s}</div>`).join('')}</div>
  <div class="grid g2"><div><h4>Parsed skills</h4><div style="margin-top:6px">${sk.map(s=>`<span class="tag">${esc(s)}</span>`).join('')||'<span class="muted">None detected</span>'}</div><h4 style="margin-top:14px">CV</h4><p class="small muted">${esc(c.cv)||'—'}</p></div>
  <div><h4>Scoring matrix</h4>${[1,2].map(n=>{ const s = c.scores[n]; return `<div class="card flat" style="padding:10px;margin-top:8px"><div class="row sp"><b>Interview ${n}</b>${s?`<span>★ ${(Object.values(s).reduce((a,b)=>a+b,0)/CRIT.length).toFixed(1)}</span>`:(stageNo===n?badge('Score now','warn'):'<span class="muted small">Not scored</span>')}</div>${s?`<div class="small muted">${CRIT.map(k=>`${k} ${s[k]}`).join(' · ')}</div>`:''}${!s&&(stageNo===n||si>=n+1)?`<button class="btn sm" style="margin-top:6px" data-act="scoreCand" data-id="${id}" data-n="${n}">Enter scores</button>`:''}</div>`; }).join('')}</div></div>`,
  actions:[{label:'Close',act:'closeModal'},{label:'Reject',cls:'bad',act:'candReject',data:`data-id="${id}"`},...(si>=2&&si<=3?[{label:'Schedule (.ics)',act:'candIcs',data:`data-id="${id}"`}]:[]),...(si>0?[{label:'← Back',act:'candMove',data:`data-id="${id}" data-d="-1"`}]:[]),...(si<STAGES.length-1?[{label:'Move to '+STAGES[si+1]+' →',cls:'pri',act:'candMove',data:`data-id="${id}" data-d="1"`}]:[])]});
}
ACT.candMove = el => { const c = DB.candidates.find(x=>x.id===el.dataset.id), d = +el.dataset.d, ni = STAGES.indexOf(c.stage)+d; if([4].includes(ni) && STAGES.indexOf(c.stage)<4 && !Object.keys(c.scores).length && !isAdmin()) return toast('Record at least one interview score before making an offer.','bad');
  c.stage = STAGES[ni]; log('Candidate moved', `${c.name} → ${c.stage}`); if(c.stage==='Hired'){ DB.onboarding.push({id:uid('ob'),emp:null,name:c.name,start:D.todayIso(),tasks:ONB_TASKS.map(t=>({t,d:0}))}); toast('Hired – onboarding checklist created','ok'); } saveDB(); closeModal(); render(); };
ACT.candReject = el => confirmBox('Reject this candidate? Record is retained per the retention schedule.', () => { const c = DB.candidates.find(x=>x.id===el.dataset.id); c.stage='Rejected'; log('Candidate rejected',c.name); saveDB(); render(); }, 'Reject');
ACT.candIcs = el => { const c = DB.candidates.find(x=>x.id===el.dataset.id), d = D.iso(D.add(D.today(),3)).replace(/-/g,''); fileDownload('interview_'+c.name.replace(/ /g,'_')+'.ics',`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//PFG HRMS//EN\r\nBEGIN:VEVENT\r\nUID:${uid('')}@pfg-hrms\r\nDTSTAMP:${d}T090000Z\r\nDTSTART:${d}T100000\r\nDTEND:${d}T110000\r\nSUMMARY:Interview – ${c.name} (${c.stage})\r\nEND:VEVENT\r\nEND:VCALENDAR`,'text/calendar'); toast('Calendar invite downloaded (edit date/time in your calendar)'); };
ACT.scoreCand = el => modal({title:`Interview ${el.dataset.n} scores`,body:`<form id="sf">${CRIT.map(k=>`<div class="field"><label>${k} (1–5)</label><select name="${k}">${[1,2,3,4,5].map(n=>`<option ${n===3?'selected':''}>${n}</option>`).join('')}</select></div>`).join('')}<p class="small muted">Scores are role-relevant criteria only. Decisions remain with the panel.</p></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Save',cls:'pri',act:'scoreSave',data:`data-id="${el.dataset.id}" data-n="${el.dataset.n}"`}]});
ACT.scoreSave = el => { const c = DB.candidates.find(x=>x.id===el.dataset.id), f = $('#sf'); c.scores[el.dataset.n] = Object.fromEntries(CRIT.map(k=>[k,+f[k].value])); log('Interview scored',c.name+' – interview '+el.dataset.n); saveDB(); closeModal(); candModal(c.id); };

/* ---------------- ONBOARDING & EXIT ---------------- */
const ONB_TASKS = ['Contract signed','Right-to-Work check (share code / PVN)','IT account & laptop issued','One Bill credentials emailed','Clocking card issued (Attendance Mgmt)','Policies acknowledged','Induction / orientation scheduled'];
VIEWS.onboarding = () => {
  const k = tabOf('onb','on'); if(k==='sp') return spAdmin();
  const on = DB.onboarding.map(o => { const done = o.tasks.filter(t=>t.d).length, pct = Math.round(done/o.tasks.length*100), nm = o.emp?empName(o.emp):o.name;
    return `<div class="card"><div class="row sp"><div class="row">${o.emp?av(o.emp,36):''}<div><b>${esc(nm)}</b><div class="small muted">Start ${fmt(o.start)}${o.orient?' · Orientation '+fmt(o.orient):''}</div></div></div><span>${pct===100?badge('Complete','ok'):badge(pct+'%','warn')}</span></div><div class="prog ${pct===100?'g':''}" style="margin:10px 0"><i style="width:${pct}%"></i></div>
    ${o.tasks.map((t,i)=>`<label class="li" style="cursor:pointer;margin:0"><input type="checkbox" style="width:auto" data-chg="obTask" data-id="${o.id}" data-i="${i}" ${t.d?'checked':''}><span class="grow" style="${t.d?'text-decoration:line-through;color:var(--muted)':''}">${esc(t.t)}</span></label>`).join('')}
    <div class="row" style="margin-top:10px"><input type="date" style="width:160px" id="or-${o.id}" value="${o.orient||''}"><button class="btn sm" data-act="orient" data-id="${o.id}">Schedule orientation</button></div></div>`; }).join('');
  const ex = DB.exits.map(x => { const e = emp(x.emp), cl = x.clear, all = Object.values(cl).every(Boolean); return `<div class="card"><div class="row sp"><div class="row">${av(e,36)}<div><b>${esc(e.name)}</b><div class="small muted">${esc(x.type)} · last day ${fmt(x.last)} · ${esc(x.reason)}</div></div></div>${all&&x.settlement==='Paid'?badge('Closed','ok'):badge('In progress','warn')}</div>
    <h4 style="margin:12px 0 6px">Clearance</h4>${Object.keys(cl).map(d=>`<label class="li" style="cursor:pointer;margin:0"><input type="checkbox" style="width:auto" data-chg="clear" data-id="${x.id}" data-d="${d}" ${cl[d]?'checked':''}> ${d}</label>`).join('')}
    <dl class="dl" style="margin-top:10px"><dt>Holiday accrual</dt><dd>${num1(x.accrual)} days to pay / deduct</dd><dt>Assets</dt><dd>${esc(x.assets)||'—'}</dd><dt>Exit interview</dt><dd>${esc(x.interview)||'<i>Not recorded</i>'}</dd><dt>Final settlement</dt><dd><select data-chg="settle" data-id="${x.id}" style="width:auto">${['Pending','Calculated','Approved','Paid'].map(s=>`<option ${x.settlement===s?'selected':''}>${s}</option>`).join('')}</select></dd></dl></div>`; }).join('');
  const reasons = {}; DB.exits.forEach(x=>reasons[x.reason]=(reasons[x.reason]||0)+1);
  return pageHead('Onboarding & Exit','New-starter checklists, IT automation, and a structured leaver clearance workflow.',`<button class="btn pri" data-act="${k==='on'?'newStarter':'newExit'}">${ico('plus')} ${k==='on'?'New starter':'Record resignation'}</button>`) + tabsHtml('onb',[['on','Onboarding'],['sp','Starter packs'],['ex','Exit & clearance']],'on') + (k==='on'?`<div class="grid g2">${on||'<div class="empty">No starters.</div>'}</div>`:`<div class="grid g2">${ex||'<div class="empty">No leavers.</div>'}</div><div class="card" style="margin-top:16px"><h3>Resignation analytics</h3>${Object.entries(reasons).map(([r,n])=>`<div class="hbar"><span>${esc(r)}</span><div class="prog"><i style="width:${n/DB.exits.length*100}%"></i></div><b>${n}</b></div>`).join('')||'<span class="muted">No data</span>'}</div>`);
};
CHG.obTask = el => { const o = DB.onboarding.find(x=>x.id===el.dataset.id), t = o.tasks[+el.dataset.i]; t.d = el.checked?1:0; if(el.checked){ if(/IT account/.test(t.t)) notify(DB.emps.filter(e=>e.depts.includes('IT')&&e.role==='manager').map(e=>e.id), `IT: set up account and equipment for ${o.emp?empName(o.emp):o.name}.`, 'dashboard'); if(/One Bill/.test(t.t)) toast('Credentials email queued to One Bill (simulated)'); } log('Onboarding task', `${t.t}: ${el.checked?'done':'reopened'}`, o.emp); saveDB(); render(); };
ACT.orient = el => { const o = DB.onboarding.find(x=>x.id===el.dataset.id), v = $('#or-'+o.id).value; if(!v) return toast('Pick a date.','bad'); o.orient = v; const t = o.tasks.find(x=>/orientation/i.test(x.t)); if(t) t.d = 1; log('Orientation scheduled',v,o.emp); saveDB(); toast('Orientation scheduled','ok'); render(); };
ACT.newStarter = () => modal({title:'New starter',body:`<form id="ns"><div class="fgrid"><div class="field"><label>Name</label><input name="n"></div><div class="field"><label>Start date</label><input type="date" name="d" value="${D.todayIso()}"></div></div><p class="small muted">Creates the standard checklist: contract, RTW, IT, One Bill, clocking card, policies, orientation.</p></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Create',cls:'pri',act:'saveStarter'}]});
ACT.saveStarter = el => submitOnce(el, () => { const f = $('#ns'); if(f.n.value.trim().length<2) return toast('Enter a name.','bad'); DB.onboarding.push({id:uid('ob'),emp:null,name:f.n.value.trim(),start:f.d.value,tasks:ONB_TASKS.map(t=>({t,d:0}))}); log('Starter added',f.n.value); saveDB(); closeModal(); render(); });
CHG.clear = el => { const x = DB.exits.find(v=>v.id===el.dataset.id); x.clear[el.dataset.d] = el.checked; log('Exit clearance',`${el.dataset.d}: ${el.checked}`,x.emp); saveDB(); render(); };
CHG.settle = el => { const x = DB.exits.find(v=>v.id===el.dataset.id); x.settlement = el.value; log('Final settlement',el.value,x.emp); saveDB(); render(); };
ACT.newExit = () => modal({title:'Record resignation / exit',body:`<form id="xf"><div class="fgrid"><div class="field full"><label>Employee</label><select name="e">${empOptions(DB.emps.filter(e=>e.status==='active'))}</select></div><div class="field"><label>Notice given</label><input type="date" name="n" value="${D.todayIso()}"></div><div class="field"><label>Last working day</label><input type="date" name="l"></div><div class="field"><label>Type</label><select name="t"><option>Resignation</option><option>Dismissal</option><option>End of contract</option><option>Retirement</option></select></div><div class="field"><label>Reason</label><select name="r">${['Career progression','Relocation','Pay','Work-life balance','Personal reasons','Other'].map(x=>`<option>${x}</option>`).join('')}</select></div></div><div id="xe" class="err"></div></form>`,actions:[{label:'Cancel',act:'closeModal'},{label:'Save',cls:'pri',act:'saveExit'}]});
ACT.saveExit = el => submitOnce(el, () => { const f = $('#xf'), er = $('#xe'); const e = emp(f.e.value); if(!f.l.value || f.l.value<f.n.value){ er.textContent='Last working day must be on or after the notice date.'; er.classList.add('show'); return; }
  if(DB.exits.some(x=>x.emp===e.id)){ er.textContent='An exit is already recorded for this employee (duplicate save prevented).'; er.classList.add('show'); return; }
  const lv = f.l.value, y = leaveYearOf(e, lv); const tmp = {...e, leaveDate:lv}; const acc = accrued(tmp,y,D.parse(lv)) + ((e.carry||{})[y]||0), b = balance(tmp,y); const bal = Math.round((acc - b.taken - b.upcoming - b.pending*0)*2)/2;
  DB.exits.push({id:uid('ex'),emp:e.id,type:f.t.value,notice:f.n.value,last:lv,reason:f.r.value,clear:{IT:false,Finance:false,'Line Manager':false},assets:'',settlement:'Pending',interview:'',accrual:bal});
  e.leaveDate = lv; e.history.unshift({t:nowStamp(),by:me().name,what:`Exit recorded – last day ${lv}`}); if(lv<=D.todayIso()) e.status='leaver'; log('Exit recorded',f.t.value+' '+lv,e.id); notify(DB.emps.filter(x=>x.role==='admin').map(x=>x.id), `Finance/IT clearance emails queued for ${e.name} (simulated).`,'onboarding'); saveDB(); closeModal(); toast('Exit recorded – clearance workflow started','ok'); render(); });
